contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function; takes target address and amount to send to multiplicate
    function run(address adr, uint amount) public payable {
        require(address(this).balance >= amount);

        // record balance before calling multiplicate
        uint before = address(c).balance;

        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(c).balance;

        // General invariant: multiplicate cannot increase c's balance above before (so after <= before)
        // and if it reverted then balance must be unchanged (after == before)
        assert((!reverted && after <= before) || (reverted && after == before));
    }

    receive() external payable {}
}

